python3 -c '
# PURGE_REFERENCE_IMPL: remove the reference implementation, then overlay the agent workspace
import os, shutil, fnmatch, subprocess
ref = "/tmp/_reference_repo"
ws = "/workspace"
HELD_OUT = ["tests"]
CODE_EXT = (".py", ".pyi", ".pyx", ".pxd", ".c", ".cc", ".cpp", ".h", ".rs")
KEEP_BASENAMES = {"conftest.py", "setup.py", "setup.cfg", "pyproject.toml", "tox.ini", "pytest.ini",
                  "sitecustomize.py", "usercustomize.py", "noxfile.py", "versioneer.py", "_version.py"}
def in_test_tree(rel):
    parts = rel.split("/")
    if parts[0] in HELD_OUT:
        return True
    if any(p in ("tests", "test", "testing") for p in parts[:-1]):
        return True
    b = parts[-1]
    return b.startswith("test_") or b.endswith("_test.py") or b == "conftest.py"
tracked = subprocess.run(["git", "-C", ref, "ls-files", "-z"], capture_output=True).stdout.decode().split("\0")
purged = 0
for rel in tracked:
    if not rel or not rel.endswith(CODE_EXT):
        continue
    if in_test_tree(rel) or os.path.basename(rel) in KEEP_BASENAMES:
        continue
    p = os.path.join(ref, rel)
    if os.path.isfile(p):
        os.remove(p)
        purged += 1
for root, dirs, files in os.walk(ref):
    dirs[:] = [d for d in dirs if d != ".git"]
    for d in list(dirs):
        if d == "__pycache__":
            shutil.rmtree(os.path.join(root, d), ignore_errors=True)
            dirs.remove(d)
    for f in files:
        if f.endswith((".so", ".pyd", ".dylib")) and not in_test_tree(os.path.relpath(os.path.join(root, f), ref)):
            os.remove(os.path.join(root, f))
            purged += 1
print("purged", purged, "reference implementation files")
excl_top = {".git", "tests", "test", "setup.py", "pyproject.toml", "setup.cfg"} | set(HELD_OUT)
excl_any = {"conftest.py", "pytest.ini", "tox.ini", "sitecustomize.py", "usercustomize.py"}
copied = 0
for root, dirs, files in os.walk(ws):
    rel = os.path.relpath(root, ws)
    if rel == ".":
        dirs[:] = [d for d in dirs if d not in excl_top]
    dirs[:] = [d for d in dirs if d not in ("__pycache__", ".git", ".pytest_cache", "tests")]
    for fn in files:
        if rel == "." and (fn in excl_top or fnmatch.fnmatch(fn, "requirements*.txt")):
            continue
        if fn in excl_any or fn.endswith((".pth", ".pyc")):
            continue
        src = os.path.join(root, fn)
        if not os.path.isfile(src):
            continue  # dangling symlink / special file: skip instead of aborting the whole overlay
        dst = os.path.join(ref, rel, fn) if rel != "." else os.path.join(ref, fn)
        try:
            os.makedirs(os.path.dirname(dst), exist_ok=True)
            shutil.copy2(src, dst)
            copied += 1
        except OSError:
            pass
print("overlaid", copied, "agent files")
'
